using Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Catalog;
public sealed class AstronomyKnowledgeCatalogEntryIdTests{[Fact]public void KnowledgeCatalogEntryId_validates_and_compares_ordinally(){var id=new AstronomyKnowledgeCatalogEntryId(AstronomyKnowledgeCatalogEntryKind.Domain," value ");Assert.Equal("value",id.Value);Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeCatalogEntryId(AstronomyKnowledgeCatalogEntryKind.Domain," "));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeCatalogEntryId((AstronomyKnowledgeCatalogEntryKind)999,"x"));Assert.Equal(id,new(AstronomyKnowledgeCatalogEntryKind.Domain,"value"));Assert.NotEqual(id,new AstronomyKnowledgeCatalogEntryId(AstronomyKnowledgeCatalogEntryKind.PayloadFamily,"value"));Assert.NotEqual(id,new AstronomyKnowledgeCatalogEntryId(AstronomyKnowledgeCatalogEntryKind.Domain,"Value"));}}
